html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clay rig preview</title><style>body{margin:0;background:#e8e8f1;color:#344458;font:14px system-ui}header{padding:24px 32px}h1{margin:0}.grid{display:grid;grid-template-columns:repeat(5,minmax(180px,1fr));gap:12px;padding:0 24px 24px}.card{border-radius:16px;background:#faf7ef;box-shadow:0 5px 12px #352b4240;padding:10px}.card h2{font-size:12px;margin:0;color:#657781}.card svg{width:100%;height:auto;overflow:visible}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}}</style></head><body><header><h1>Clay character rig</h1><p>10 appearances × 5 states · articulated SVG parts · preview only</p></header><main class="grid" id="grid"></main><script>
const assets=ASSETS, meta=META, NS='http://www.w3.org/2000/svg';const grid=document.getElementById('grid'),states=['working','phone','sleeping','away','idle'], rigs=[];
function node(tag,attrs={}){let n=document.createElementNS(NS,tag);for(let [k,v] of Object.entries(attrs))n.setAttribute(k,v);return n}
function part(parent,id,key){let path=`characters/${id}/${key}.svg`, m=meta.files[path], wrap=node('g');let svg=new DOMParser().parseFromString(assets[path],'image/svg+xml').documentElement;svg=document.importNode(svg,true);svg.setAttribute('x',m.viewBox[0]);svg.setAttribute('y',m.viewBox[1]);svg.setAttribute('width',m.size[0]);svg.setAttribute('height',m.size[1]);wrap.appendChild(svg);parent.appendChild(wrap);return wrap}
function addAt(parent,id,key,x,y){let g=part(parent,id,key);g.setAttribute('transform',`translate(${x} ${y})`);return g}
for(const id of meta.appearanceIds)for(const state of states){let c=document.createElement('article');c.className='card';let h=document.createElement('h2');h.textContent=`${id} · ${state}`;c.appendChild(h);let svg=node('svg',{viewBox:'-110 -120 220 200',role:'img','aria-label':`${id} ${state}`});c.appendChild(svg);grid.appendChild(c);let shadow=node('ellipse',{cx:0,cy:62,rx:45,ry:9,fill:'#382f46',opacity:.27});svg.appendChild(shadow);let character=node('g',{});svg.appendChild(character);for(let side of ['l','r'])addAt(character,id,`leg-${state==='away'?'':'seated-'}${side}`,side==='l'?-12:12,35);let body=part(character,id,'body');let arms=[];for(let [side,sgn] of [['l',-1],['r',1]]){let shoulder=addAt(body,id,`arm-upper-${side}`,sgn*22,-15);let elbow=addAt(shoulder,id,`arm-lower-${side}`,sgn*21,20);let hand=addAt(elbow,id,`hand-${side}`,sgn*13,18);if(state==='phone' && side==='r'){shoulder.setAttribute('transform','translate(22 -15) rotate(-160)');elbow.setAttribute('transform','translate(21 20) rotate(75)');let phone=node('g',{transform:'translate(13 18) rotate(70)'});let shell=node('rect',{x:-8,y:-19,width:16,height:26,rx:4,fill:'#526586'});let screen=node('rect',{x:-5,y:-16,width:10,height:19,rx:2,fill:'#b6f2ff'});phone.appendChild(shell);phone.appendChild(screen);elbow.appendChild(phone)}arms.push(shoulder)}let head=addAt(body,id,'head',0,-42);addAt(head,id,`face-${state}`,0,0);addAt(head,id,'hair',0,0);if(state==='phone'){let glow=node('ellipse',{cx:13,cy:5,rx:15,ry:10,fill:'#80dfff',opacity:.38,transform:'rotate(-18 13 5)'});head.appendChild(glow)}if(state==='sleeping')head.setAttribute('transform','translate(14 -21) rotate(65)');rigs.push({character,head,arms,state})}
function animate(ms){let t=ms/1000;for(const r of rigs){if(r.state==='working'){r.arms.forEach((a,i)=>{let s=i?1:-1;a.setAttribute('transform',`translate(${s*22} -15) rotate(${s*18*Math.sin(t*34)})`)});r.character.setAttribute('transform',`translate(${2*Math.sin(t*23)} 0)`)}else if(r.state==='away'){r.arms.forEach((a,i)=>{let s=i?1:-1;a.setAttribute('transform',`translate(${s*22} -15) rotate(${s*18*Math.sin(t*8)})`)})}else if(r.state==='phone')r.head.setAttribute('transform','translate(0 -38) rotate(12)')}requestAnimationFrame(animate)}requestAnimationFrame(animate);
</script></body></html>'''.replace('ASSETS',json.dumps(preview_assets,ensure_ascii=False)).replace('META',json.dumps(manifest,ensure_ascii=False))
